    { "@type": "Question", "name": "How much does stump grinding cost in NE Ohio?", "acceptedAnswer": { "@type": "Answer", "text": "Stump grinding starts at a $150 per-job minimum. Per-stump pricing typically runs $150–$250 for small stumps under 12 inches, $200–$300 for medium stumps 12–24 inches, $400–$800 for large stumps 24–36 inches, and $500–$1,000 for very large stumps over 36 inches. Cleanup or topsoil backfill adds $50–$150 per job. Multi-stump packages and post-removal package rates lower the per-stump cost." } },
    { "@type": "Question", "name": "What's the difference between stump grinding and stump removal?", "acceptedAnswer": { "@type": "Answer", "text": "Stump grinding pulverizes the stump and surface roots in place to 6–12 inches below grade — fast, less invasive, and it leaves the deeper root system intact. Full-excavation stump removal pulls the entire root ball out with a mini-excavator — it leaves a planting hole or clean foundation pad, but it's more invasive, costs more, and takes longer. Most homeowners want grinding; landscapers and builders sometimes need removal." } },
    { "@type": "Question", "name": "How deep do you grind the stump?", "acceptedAnswer": { "@type": "Answer", "text": "Standard grinding is 6–12 inches below grade. Six inches is enough for re-sodding lawn or planting beds; 12 inches is deeper and supports new tree planting in the same spot. Tell us your plan for the spot and we grind to the right depth." } },
    { "@type": "Question", "name": "Do you remove the wood chips?", "acceptedAnswer": { "@type": "Answer", "text": "Customer choice. Three options: leave the chips as mulch on-site (free), haul them off (+$50–$150), or backfill the grinding hole with topsoil and seed (+$100–$150). Most residential customers either leave chips or backfill with topsoil; commercial customers usually want haul-off." } },
    { "@type": "Question", "name": "Can I plant a new tree where the stump was ground?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — but plan for it. Standard 6-inch grinding leaves enough root and chip residue that a new tree planted in the exact same spot may struggle. For replanting, ask for 12-inch grinding plus topsoil backfill, and consider planting 2–3 feet from the original trunk position rather than directly over it." } },
    { "@type": "Question", "name": "Will grinding damage my lawn or driveway?", "acceptedAnswer": { "@type": "Answer", "text": "Grinding is much less invasive than full-excavation removal. The compact grinder works in a small footprint and leaves only the immediate stump area disturbed. Driveways are protected with plywood mats during equipment movement on premium properties. Some lawn impact is unavoidable in the immediate stump zone, but routine cleanup and topsoil-and-seed restore the area within one growing season." } },
    { "@type": "Question", "name": "Do you call 811 before grinding?", "acceptedAnswer": { "@type": "Answer", "text": "Yes — 811 utility mark-out is built into our standard operating procedure on every grinding job, because the grinder cuts below grade near potential buried utilities. It protects your gas, water, and electric lines and protects you from a damaged-utility liability claim. We schedule the locate before the grinder arrives on site." } }
